const crypto = require("crypto")

function hashSync(password, saltRounds = 10) {
  const salt = crypto.randomBytes(16).toString("hex")
  const iterations = Math.max(1, Number(saltRounds) * 1000)
  const derived = crypto.pbkdf2Sync(String(password), salt, iterations, 32, "sha256").toString("hex")
  return `pbkdf2$${iterations}$${salt}$${derived}`
}

function compareSync(password, hashedValue) {
  const parts = String(hashedValue).split("$")
  if (parts.length !== 4 || parts[0] !== "pbkdf2") {
    return false
  }

  const iterations = Number(parts[1])
  const salt = parts[2]
  const expected = parts[3]
  const derived = crypto.pbkdf2Sync(String(password), salt, iterations, 32, "sha256").toString("hex")
  return crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(derived))
}

function hash(password, saltRounds) {
  return Promise.resolve(hashSync(password, saltRounds))
}

function compare(password, hashedValue) {
  return Promise.resolve(compareSync(password, hashedValue))
}

module.exports = {
  compare,
  compareSync,
  hash,
  hashSync
}
